def get_flags_from_context() ->Dict[str, str]:
    flags = {}
    try:
        ctx = click.get_current_context()
        if ctx and ctx.command:
            # Traverse the command hierarchy to collect all parameters
            def collect_params(command):
                params = {}
                if hasattr(command, 'params'):
                    for param in command.params:
                        if isinstance(param, click.Option):
                            # Map each option string to the parameter name
                            for opt_string in param.opts:
                                params[opt_string] = param.name
                if hasattr(command, 'commands'):
                    for subcommand in command.commands.values():
                        params.update(collect_params(subcommand))
                return params

            flags = collect_params(ctx.command)
    except RuntimeError:
        # No active Click context
        pass

    return flags
